  'home.b2b.tier2': 'நிறுவன & உச்சிமாநாட்டுத் தொகுப்பு (100 - 500 பொருட்கள்)',
  'home.b2b.tier2.desc': 'அரசு விருந்து நினைவுப் பரிசுகள், கையால் செய்யப்பட்ட பட்டு சால்வைகள் மற்றும் கூட்டு புவியியல் குறியீட்டுக் குழு ஒதுக்கீடுகள்.',
