  'literacy.tutorial.title': 'கலாகிருதிக்கு நல்வரவு — இது எவ்வாறு செயல்படுகிறது',
  'literacy.tutorial.subtitle': 'கைவினைஞர்களுக்காக வடிவமைக்கப்பட்டது. தொழில்நுட்ப கணினி அறிவு இல்லாமலேயே உங்கள் கைவினைப் பொருட்களை இந்தியா முழுவதும் விற்கலாம்.',
  'literacy.tutorial.step1Title': '1. உங்கள் தாய்மொழியில் பேசுங்கள்',
  'literacy.tutorial.step1Desc': 'தட்டச்சு செய்ய வேண்டிய அவசியமில்லை. உங்கள் கைவினைப்பொருளை விவரிக்கும் ஒரு சிறிய குரல் குறிப்பை பதிவு செய்தால் போதும். எங்கள் AI அதை உரைநடையில் மாற்றி பட்டியலை உருவாக்குகிறது.',
  'literacy.tutorial.step2Title': '2. தானியங்கி AI ஸ்டுடியோ வெளிச்சம்',
  'literacy.tutorial.step2Desc': 'உங்கள் மொபைலில் எளிய புகைப்படங்களை எடுங்கள். எங்கள் AI பணிமனை பின்னணியை சுத்தம் செய்து இயற்கை வெளிச்சத்தை சமன் செய்கிறது.',
  'literacy.tutorial.step3Title': '3. நியாயமான விலை வழிகாட்டுதல்',
  'literacy.tutorial.step3Desc': 'உங்கள் மூலப்பொருள் மற்றும் தினசரி உழைப்புச் செலவை நாங்கள் கணக்கிடுகிறோம், எனவே நீங்கள் ஒருபோதும் உங்கள் தகுதியான வருமானத்திற்குக் குறைவாக விற்க மாட்டீர்கள்.',
  'literacy.tutorial.step4Title': '4. நேரடி வங்கி கொடுப்பனவுகள்',
  'literacy.tutorial.step4Desc': 'வாங்குபவர்கள் DBT மூலம் உங்கள் சரிபார்க்கப்பட்ட வங்கிக் கணக்கிற்கு நேரடியாக பணம் செலுத்துகிறார்கள். பூஜ்ஜிய இடைத்தரகர் கட்டணம்.',
  'literacy.tutorial.close': 'புரிந்தது, தொடங்குவோம்',
  'literacy.tutorial.open': 'இது எவ்வாறு செயல்படுகிறது',
