  'privacy.section3.bullet4': 'எஸ்எம்எஸ் (SMS) மற்றும் மின்னஞ்சல் மூலம் விநியோகம் மற்றும் நிலை அறிவிப்புகளை உறுதி செய்தல்.',
  'privacy.section4.heading': '4. மூன்றாம் தரப்பு தரவு விற்பனை மீதான முழுமையான தடை',
  'privacy.section5.heading': '5. கிரிப்டோகிராஃபிக் பாதுகாப்பு & குக்கீ கொள்கை',
  'privacy.section6.heading': '6. தரவு உரிமையாளர் உரிமைகள் & குறைதீர்ப்பு வழிமுறை',
