  'terms.headTitle': 'பயன்பாட்டு விதிமுறைகள் — {appName}',
  'terms.kicker': 'அரசு நிர்வாகம் & கைவினைக் குழு ஆணை',
  'terms.title': 'பயன்பாட்டு விதிமுறைகள்',
  'terms.lastUpdated': 'கடைசியாக புதுப்பிக்கப்பட்டது: செப்டம்பர் 2026 • சமூக நீதி மற்றும் அதிகாரமளித்தல் அமைச்சகம், இந்திய அரசு',
  'terms.section1.heading': '1. தள ஆணை & பொதுக் கட்டமைப்பு',
  'terms.section2.heading': '2. புவியியல் குறியீடுகள் (GI) & நம்பகத்தன்மை தரம்',
  'terms.section3.heading': '3. 100% நேரடி கொடுப்பனவுகள் & 0% தளக் கழிவுகள்',
  'terms.section4.heading': '4. ஆர்டரின் பேரில் தயாரித்தல் & நிறுவன நிறைவேற்றம்',
