  "trends.sourceLabel": "ஆதாரம்: {domain}",
  "trends.item1.title": "ஐரோப்பிய கோடைகால சேகரிப்பில் அஜ்ரக் மற்றும் எர்த் டோன்கள்",
  "trends.item1.desc": "இயற்கை சாயங்கள் மற்றும் பூட்டிக் தேவையில் அதிகரித்து வரும் நவீன ஆடைகள்.",
  "trends.item1.curator": "மீரா ராவ் (அமைச்சக சோர்சிங் ஆலோசகர்)",
  "trends.item2.title": "காதர் பண்டிகை ஆடைகளில் சமகால சர்தோசி பார்டர்",
  "trends.item2.desc": "காதர் ஆடைகளில் சர்தோசி பார்டர்களின் வளர்ந்து வரும் தேவை.",
  "trends.item2.curator": "ராஜேஷ் சிங்கானியா (தலைமை நெசவாளர், வாரணாசி)",
  "trends.item3.title": "கைவினை மதுபானி மேஜை துணி மற்றும் பீங்கான் அலங்காரங்கள்",
  "trends.item3.desc": "பாரம்பரிய மிதिला இயற்கை வண்ணங்களால் அலங்கரிக்கப்பட்ட லினன்.",
  "trends.item3.curator": "சீதா தேவி (நாட்டுப்புறக் கலைஞர், மதுபானி)",
  "trends.item4.title": "கார்ப்பரேட் அலுவலக உடைக்காக சந்தேரி புடவைகள்",
  "trends.item4.desc": "அலுவலக பயன்பாட்டிற்கு சந்தேரி நெசவு பிரபலமடைந்து வருகிறது.",
  "trends.item4.curator": "டாக்டர் சுனிதா படேல் (கிளஸ்டர் வளர்ச்சி அலுவலர், மத்திய பிரதேசம்)",
  "trends.modal.heading": "சமூகப் போக்கு அல்லது பூட்டிக் உத்வேகத்தைப் பகிரவும்",
  "trends.modal.intro": "நல்ல ரீல் அல்லது பூட்டிக் தொகுப்பைக் கண்டீர்களா? தேவைக்கேற்ப உற்பத்தி செய்ய கைவினைஞர்களுடன் பகிர்ந்து கொள்ளுங்கள்.",
  "trends.modal.urlLabel": "சமூக ஊடக இணைப்பு",
  "trends.modal.urlDesc": "இன்ஸ்டாகிராம், பின்டெரெஸ்ட், யூடியூப் இணைப்பை ஒட்டவும்",
  "trends.modal.headlineLabel": "தலைப்பு",
  "trends.modal.headlineDesc": "இது வாங்குபவர்களுக்கு ஏன் முக்கியமானது?",
  "trends.modal.headlinePlaceholder": "எ.கா: பூட்டிக்கில் பிளாக் பிரிண்ட் நேப்கின்கள்",
  "trends.modal.platformLabel": "தளம்",
  "trends.modal.craftLabel": "கைவினைப் பிரிவு",
  "trends.modal.publish": "பலகையில் வெளியிடுங்கள்",
  "trends.modal.sharing": "பகிரப்படுகிறது...",
  "trends.toast.shared": "உத்வேகம் கைவினைஞர்களுடன் பகிரப்பட்டது.",
  "trends.toast.saved": "உங்கள் கிளஸ்டர் பலகையில் சேமிக்கப்பட்டது.",
  "home.sourcing.kicker": "ஆண்டு முழுவதும் சோர்சிங் & பூட்டிக் கூட்டாண்மை",
  "home.sourcing.desc": "சரிபார்க்கப்பட்ட சில்லறை விற்பனையாளர்கள், சுயாதீன பூட்டிக் ஸ்டுடியோக்கள் மற்றும் ஏற்றுமதி நிறுவனங்கள் சான்றளிக்கப்பட்ட கிளஸ்டர்களிலிருந்து நேரடியாக உண்மையான கைவினைப் பொருட்களை வாங்குகின்றன.",
  "home.sourcing.viewLots": "சோர்சிங் லாட்களைக் காண்க",
  "home.sourcing.viewTrends": "சந்தை போக்குகளைக் காண்க",
